// Calcule la week_id ISO 8601 de la semaine courante (Europe/Paris).
// Convention: la semaine ISO commence le lundi, et la semaine 1
// contient le 1er jeudi de l'année.
const now = new Date();
const utc = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const dayNum = utc.getUTCDay() || 7;
utc.setUTCDate(utc.getUTCDate() + 4 - dayNum);
const yearStart = new Date(Date.UTC(utc.getUTCFullYear(), 0, 1));
const week = Math.ceil(((utc.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
const weekId = `${utc.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
// Calcule aussi le lundi 00:00 de la semaine (utile pour le filtre Supabase).
const monday = new Date(utc);
monday.setUTCDate(utc.getUTCDate() - 3); // utc est ajusté sur le jeudi de la semaine
monday.setUTCHours(0, 0, 0, 0);
return [{ json: { week_id: weekId, week_start_iso: monday.toISOString() } }];

// Compte les clean_posts pertinents depuis le lundi de la semaine.
// Utilise le client Supabase via $env (le runtime n8n a accès à process.env).
const { createClient } = require('@supabase/supabase-js');
const sb = createClient($env.SUPABASE_URL, $env.SUPABASE_SERVICE_ROLE_KEY);
const weekId = $node['Code: compute_week_id'].json.week_id;
const weekStartIso = $node['Code: compute_week_id'].json.week_start_iso;
const { count, error } = await sb
  .from('clean_posts')
  .select('post_id', { count: 'exact', head: true })
  .eq('is_relevant', true);
if (error) throw new Error('volume_check_failed: ' + error.message);
const sufficient = (count ?? 0) >= 10;
return [{ json: { week_id: weekId, week_start_iso: weekStartIso, clean_posts_count: count ?? 0, sufficient } }];

// Vérifie que weekly_reports a bien les 6 colonnes JSON alimentées
// pour la week_id de la run.
const { createClient } = require('@supabase/supabase-js');
const sb = createClient($env.SUPABASE_URL, $env.SUPABASE_SERVICE_ROLE_KEY);
const weekId = $node['Code: compute_week_id'].json.week_id;
const { data, error } = await sb
  .from('weekly_reports')
  .select('week_id, linkedin_trends_json, insurance_trends_json, angles_json, winners_json, visuals_json, timing_json')
  .eq('week_id', weekId)
  .maybeSingle();
if (error) throw new Error('weekly_reports_select_failed: ' + error.message);
if (!data) throw new Error('weekly_reports_row_missing: ' + weekId);
const missing = [];
if (!data.linkedin_trends_json) missing.push('linkedin_trends_json');
if (!data.insurance_trends_json) missing.push('insurance_trends_json');
if (!data.angles_json) missing.push('angles_json');
if (!data.winners_json) missing.push('winners_json');
if (!data.visuals_json) missing.push('visuals_json');
if (!data.timing_json) missing.push('timing_json');
if (missing.length > 0) {
  throw new Error('incomplete_weekly_report: missing=' + missing.join(','));
}
return [{ json: { week_id: weekId, complete: true, columns_ok: 6 } }];

